import numpy as np

try:
    from scipy.optimize import minimize
    _HAS_SCIPY = True
except Exception:
    _HAS_SCIPY = False


def _triplets(n=13):
    """All C(n,3) index triplets, precomputed once."""
    return np.array([(i, j, k) for i in range(n) for j in range(i + 1, n)
                     for k in range(j + 1, n)])


def _areas(P, idx):
    """Areas of all triangles of point set P (vectorized cross products)."""
    a, b, c = P[idx[:, 0]], P[idx[:, 1]], P[idx[:, 2]]
    return 0.5 * np.abs((b[:, 0] - a[:, 0]) * (c[:, 1] - a[:, 1])
                        - (b[:, 1] - a[:, 1]) * (c[:, 0] - a[:, 0]))


def _softmin_obj(x, tau, idx):
    """Stable negative log-sum-exp soft-min of triangle areas; smooth
    max-min surrogate that becomes exact as tau -> 0."""
    P = x.reshape(-1, 2)
    ar = _areas(P, idx) + 1e-12
    m = ar.min()
    return m - tau * np.log(np.sum(np.exp(-(ar - m) / tau)))


def _hull_area(P):
    """Convex hull area via monotone-chain + shoelace formula."""
    pts = P[np.lexsort((P[:, 1], P[:, 0]))]
    def half(pts):
        h = []
        for p in pts:
            while len(h) >= 2 and ((h[-1][0] - h[-2][0]) * (p[1] - h[-2][1])
                                   - (h[-1][1] - h[-2][1]) * (p[0] - h[-2][0])) <= 0:
                h.pop()
            h.append(p)
        return h
    lower = half(pts)
    upper = half(pts[::-1])
    hull = np.array(lower[:-1] + upper[:-1])
    x, y = hull[:, 0], hull[:, 1]
    return 0.5 * abs(np.dot(x, np.roll(y, -1)) - np.dot(y, np.roll(x, -1)))


def heilbronn_convex13() -> np.ndarray:
    """
    Deterministic multistart max-min optimization of the minimum triangle area
    for exactly 13 points. Structured (8-point outer ring + 5-point inner ring)
    and perturbed/random starts are annealed through an SLSQP log-sum-exp
    soft-min with decreasing temperature. The normalized objective is
    affine-invariant, so raw areas are optimized directly. Best valid
    incumbent is always retained and returned as a finite (13, 2) array.
    """
    n = 13
    idx = _triplets(n)
    best, best_val = None, -np.inf

    starts = []
    # Structured near-uniform start: 8 outer + 5 inner = 13 points.
    ang = 2 * np.pi * np.arange(8) / 8
    ring = 0.5 + 0.45 * np.stack([np.cos(ang), np.sin(ang)], axis=1)
    ang5 = 2 * np.pi * np.arange(5) / 5 + 0.3
    ring2 = 0.5 + 0.17 * np.stack([np.cos(ang5), np.sin(ang5)], axis=1)
    base = np.vstack([ring, ring2])
    assert base.shape == (n, 2)
    starts.append(base)
    # Perturbed structured starts (symmetry breaking); guard shapes.
    for s in range(3):
        rng = np.random.default_rng(seed=500 + s)
        cand = base + 0.04 * (rng.random((n, 2)) - 0.5)
        if cand.shape == (n, 2):
            starts.append(cand)
    # Deterministic random multistart.
    for s in range(4):
        rng = np.random.default_rng(seed=1000 + s)
        cand = rng.random((n, 2))
        if cand.shape == (n, 2):
            starts.append(cand)

    if not _HAS_SCIPY:
        for P in starts:
            v = _areas(P, idx).min() / max(_hull_area(P), 1e-12)
            if v > best_val:
                best_val, best = v, P.copy()
        return np.asarray(best, dtype=float)

    for P0 in starts:
        x = np.clip(np.asarray(P0, dtype=float), 1e-3, 1 - 1e-3).ravel().copy()
        if x.size != 2 * n:
            continue
        try:
            # Anneal soft-min temperature toward the exact max-min problem.
            for tau in (0.02, 0.008, 0.003, 0.001, 3e-4):
                res = minimize(_softmin_obj, x, args=(tau, idx),
                               method="SLSQP",
                               options={"maxiter": 250, "ftol": 1e-12})
                if np.all(np.isfinite(res.x)):
                    x = res.x
        except Exception:
            pass  # keep incumbent x

        P = x.reshape(n, 2)
        if np.all(np.isfinite(P)):
            ha = max(_hull_area(P), 1e-12)
            v = _areas(P, idx).min() / ha
            if v > best_val:
                best_val, best = v, P.copy()

    if best is None:
        best = np.asarray(starts[0], dtype=float)
    best = np.asarray(best, dtype=float).reshape(n, 2)
    best -= best.mean(axis=0)
    scale = np.abs(best).max()
    if scale > 0:
        best /= scale
    return best


